  `resolved_at` DATETIME NULL,
  `resolved_by` BIGINT NULL,
  `resolution_note` VARCHAR(500) NULL,
  KEY `idx_escrow_status` (`status`, `id`),
  CONSTRAINT `ck_escrow_parties` CHECK (payer_id <> payee_id),
  CONSTRAINT `ck_escrow_resolution` CHECK (status NOT IN ('RELEASED', 'REFUNDED') OR (resolved_at IS NOT NULL AND resolved_by IS NOT NULL AND resolution_note IS NOT NULL)),
  CONSTRAINT `ck_exchange_escrows_amount` CHECK (amount > 0),
  CONSTRAINT `ck_exchange_escrows_status` CHECK (status IN ('HELD', 'READY', 'RELEASED', 'REFUNDED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `product_image_features` (
  `image_id` BIGINT NOT NULL PRIMARY KEY,
  `embedding` JSON NOT NULL,
  `model_name` VARCHAR(100) NOT NULL,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  CONSTRAINT `ck_image_embedding` CHECK (JSON_TYPE(embedding) = 'ARRAY' AND JSON_LENGTH(embedding) > 0)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `product_classifications` (
  `product_id` BIGINT NOT NULL PRIMARY KEY,
  `status` VARCHAR(20) NOT NULL DEFAULT 'PENDING',
  `is_comic` BOOLEAN NULL,
  `confidence` DECIMAL(5,4) NULL,
  `model_name` VARCHAR(100) NULL,
  `classified_at` DATETIME NULL,
  `error_message` TEXT NULL,
  CONSTRAINT `ck_classification_result` CHECK (status <> 'SUCCEEDED' OR (is_comic IS NOT NULL AND confidence IS NOT NULL AND model_name IS NOT NULL AND classified_at IS NOT NULL)),
  CONSTRAINT `ck_product_classifications_status` CHECK (status IN ('PENDING', 'SUCCEEDED', 'FAILED')),
  CONSTRAINT `ck_product_classifications_confidence` CHECK (confidence BETWEEN 0 AND 1)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `consultation_sessions` (
  `id` BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  `user_id` BIGINT NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `consultation_messages` (
  `id` BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  `session_id` BIGINT NOT NULL,
  `sender_type` VARCHAR(20) NOT NULL,
  `content` TEXT NOT NULL,
  `suggested_product_ids` JSON NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  KEY `idx_consultation_chat` (`session_id`, `id`),
  CONSTRAINT `ck_consultation_messages_sender_type` CHECK (sender_type IN ('USER', 'ASSISTANT'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE `notifications` (
  `id` BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
  `user_id` BIGINT NOT NULL,
  `order_id` BIGINT NOT NULL,
  `title` VARCHAR(200) NOT NULL,
  `content` TEXT NOT NULL,
  `deduplication_key` VARCHAR(150) NOT NULL UNIQUE,
  `read_at` DATETIME NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

